"use strict";(globalThis.webpackChunkdocs_site||=[]).push([[2256],{7674(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"manual":[{"type":"category","label":"Getting started","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/getting-started/installation","label":"Installation","docId":"getting-started/installation","unlisted":false},{"type":"link","href":"/docs/getting-started/quick-start","label":"Quick start","docId":"getting-started/quick-start","unlisted":false}]},{"type":"link","href":"/docs/","label":"Overview","docId":"intro","unlisted":false},{"type":"category","label":"Architecture","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/architecture/overview","label":"System overview","docId":"architecture/overview","unlisted":false},{"type":"link","href":"/docs/architecture/repository-layout","label":"Repository layout","docId":"architecture/repository-layout","unlisted":false}]},{"type":"category","label":"Data","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/data/datasets","label":"Datasets","docId":"data/datasets","unlisted":false},{"type":"link","href":"/docs/data/landmark-extraction","label":"Landmark extraction","docId":"data/landmark-extraction","unlisted":false},{"type":"link","href":"/docs/data/aligned-real-frames","label":"Aligned real frames","docId":"data/aligned-real-frames","unlisted":false}]},{"type":"category","label":"Static recognition","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/static-recognition/dh-gat-v2","label":"DH-GAT v2 model","docId":"static-recognition/dh-gat-v2","unlisted":false},{"type":"link","href":"/docs/static-recognition/training","label":"Training and calibration","docId":"static-recognition/training","unlisted":false},{"type":"link","href":"/docs/static-recognition/hold-detection","label":"Hold detection and typing","docId":"static-recognition/hold-detection","unlisted":false}]},{"type":"category","label":"Continuous recognition","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/continuous-recognition/features-and-models","label":"Features and models","docId":"continuous-recognition/features-and-models","unlisted":false},{"type":"link","href":"/docs/continuous-recognition/training-and-decoding","label":"Training, decoding and key frames","docId":"continuous-recognition/training-and-decoding","unlisted":false},{"type":"link","href":"/docs/continuous-recognition/live-streaming","label":"Live streaming","docId":"continuous-recognition/live-streaming","unlisted":false}]},{"type":"category","label":"3D avatar","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/avatar/pose-library","label":"Pose library","docId":"avatar/pose-library","unlisted":false},{"type":"link","href":"/docs/avatar/geometric-transformations","label":"Geometric transformations (touching joints)","docId":"avatar/geometric-transformations","unlisted":false},{"type":"link","href":"/docs/avatar/renderer","label":"The 3D signer","docId":"avatar/renderer","unlisted":false}]},{"type":"category","label":"Web app","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/web-app/user-manual","label":"User manual","docId":"web-app/user-manual","unlisted":false},{"type":"link","href":"/docs/web-app/api-reference","label":"API reference","docId":"web-app/api-reference","unlisted":false}]},{"type":"category","label":"Evaluation","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/evaluation/benchmark","label":"Benchmark","docId":"evaluation/benchmark","unlisted":false},{"type":"link","href":"/docs/evaluation/limitations","label":"Limitations","docId":"evaluation/limitations","unlisted":false}]},{"type":"category","label":"Reference","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/reference/commands","label":"Commands and reproducibility","docId":"reference/commands","unlisted":false},{"type":"link","href":"/docs/reference/design-decisions","label":"Design decisions","docId":"reference/design-decisions","unlisted":false},{"type":"link","href":"/docs/reference/troubleshooting","label":"Troubleshooting","docId":"reference/troubleshooting","unlisted":false},{"type":"link","href":"/docs/reference/future-work","label":"Future work","docId":"reference/future-work","unlisted":false}]}]},"docs":{"architecture/overview":{"id":"architecture/overview","title":"System overview","description":"The system has two halves that share the same hand-landmark representation: a recognition half (sign \u2192 text) and a synthesis half (text \u2192 sign).","sidebar":"manual"},"architecture/repository-layout":{"id":"architecture/repository-layout","title":"Repository layout","description":"Not in the repository (listed in .gitignore): data/ (datasets), cache/ (landmark caches), logs/, results/.","sidebar":"manual"},"avatar/geometric-transformations":{"id":"avatar/geometric-transformations","title":"Geometric transformations (touching joints)","description":"A two-handed ISL letter is defined by contacts such as \\"index fingertip rests on the other palm\\". Raw landmarks only give noisy joint centres, so a raw pose shows gaps or fingers that poke through the other hand. src/avatar/touch.py repairs every pose with four geometric steps.","sidebar":"manual"},"avatar/pose-library":{"id":"avatar/pose-library","title":"Pose library","description":"The avatar does not use hand-modelled poses: every letter\'s pose is derived from the real data, so the avatar signs what the recogniser was trained to recognise.","sidebar":"manual"},"avatar/renderer":{"id":"avatar/renderer","title":"The 3D signer","description":"app/static/js/avatar.js draws an upper-body signer \u2014 head, shoulders, torso in a kurta, two sleeved arms and two skinned hands \u2014 with Three.js (vendored in app/static/vendor/, so the app works offline).","sidebar":"manual"},"continuous-recognition/features-and-models":{"id":"continuous-recognition/features-and-models","title":"Features and models","description":"Continuous fingerspelling is spelling a whole name without stopping at each letter \u2014 the hands flow from shape to shape and letters are co-articulated. We treat it as sequence labelling with CTC (Connectionist Temporal Classification): the model emits, for every video frame, a probability over 26 letters plus a blank, and the loss sums over every frame-to-letter alignment, so no frame-level labels are needed.","sidebar":"manual"},"continuous-recognition/live-streaming":{"id":"continuous-recognition/live-streaming","title":"Live streaming","description":"Reading a recorded video is easy: the whole clip is available. Reading a webcam is harder \u2014 letters arrive one frame at a time, the camera may run at 15, 30 or 60 frames per second, and the answer on screen should be right and quick, even when the signer changes letters fast. This page describes how the live recogniser (src/pipeline/streaming.py) does it.","sidebar":"manual"},"continuous-recognition/training-and-decoding":{"id":"continuous-recognition/training-and-decoding","title":"Training, decoding and key frames","description":"Training","sidebar":"manual"},"data/aligned-real-frames":{"id":"data/aligned-real-frames","title":"Aligned real frames","description":"The problem with the old frames","sidebar":"manual"},"data/datasets":{"id":"data/datasets","title":"Datasets","description":"Four collections are used. None of them is redistributed with the repository.","sidebar":"manual"},"data/landmark-extraction":{"id":"data/landmark-extraction","title":"Landmark extraction","description":"All models start from MediaPipe HandLandmarker (hand_landmarker.task): up to two hands, 21 joints each, (x, y, z) with x, y \u2208 [0, 1] of the image and z relative to that hand\'s wrist.","sidebar":"manual"},"evaluation/benchmark":{"id":"evaluation/benchmark","title":"Benchmark","description":"All numbers are produced by scripts in the repository and written into this page by","sidebar":"manual"},"evaluation/limitations":{"id":"evaluation/limitations","title":"Limitations","description":"1 \xb7 Generalisation to a new camera / signer","sidebar":"manual"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation","description":"Requirements","sidebar":"manual"},"getting-started/quick-start":{"id":"getting-started/quick-start","title":"Quick start","description":"1 \xb7 Start the web app","sidebar":"manual"},"intro":{"id":"intro","title":"Overview","description":"Varna (Sanskrit for letter) recognises and synthesises Indian Sign Language (ISL) fingerspelling \u2014 the A\u2013Z hand alphabet used to spell names and words. It works in both directions:","sidebar":"manual"},"reference/commands":{"id":"reference/commands","title":"Commands and reproducibility","description":"All commands run from the repository root. The datasets must be placed under data/:","sidebar":"manual"},"reference/design-decisions":{"id":"reference/design-decisions","title":"Design decisions","description":"Every significant choice, with the reason and the alternative that was rejected \u2014 material for a viva.","sidebar":"manual"},"reference/future-work":{"id":"reference/future-work","title":"Future work","description":"| Idea | Expected benefit |","sidebar":"manual"},"reference/troubleshooting":{"id":"reference/troubleshooting","title":"Troubleshooting","description":"| Symptom | Cause / fix |","sidebar":"manual"},"static-recognition/dh-gat-v2":{"id":"static-recognition/dh-gat-v2","title":"DH-GAT v2 model","description":"DH-GAT classifies a single frame into one of the 26 letters from the two hands\' 21 joints each.","sidebar":"manual"},"static-recognition/hold-detection":{"id":"static-recognition/hold-detection","title":"Hold detection and typing","description":"The classifier produces a guess for every frame, including the frames in which the hands are travelling between letters. src/pipeline/hold.py decides when a letter has really been signed.","sidebar":"manual"},"static-recognition/training":{"id":"static-recognition/training","title":"Training and calibration","description":"Data","sidebar":"manual"},"web-app/api-reference":{"id":"web-app/api-reference","title":"API reference","description":"The server (app/server.py, Starlette + uvicorn) exposes a small HTTP/WebSocket API on http8000.","sidebar":"manual"},"web-app/user-manual":{"id":"web-app/user-manual","title":"User manual","description":"Start the server with python app/server.py and open http8000. The header has five pages \u2014 Recognise, Sign, Alphabet, Results and Docs (this manual, shown inside the site) \u2014 a status light (models ready) and a theme switch (light or dark, remembered).","sidebar":"manual"}}}}')}}]);